"""Bilingual product story using real app widgets and illustrative content."""
from html import escape


def render_home(lang, email):
    zh = lang == 'zh'
    t = lambda a, b: a if zh else b
    base = '/memory-music-support/'
    prefix = base if zh else base + 'en/'
    def screen(file, alt, eager=False):
        w,h = (1206,2622) if file.startswith('iphone') else ((2048,2732) if file.startswith('ipad') else (2560,1600))
        return f'<button class="screen" data-zoom aria-label="{t("放大查看：", "Enlarge: ")}{escape(alt)}"><img src="{base}assets/{file}.png" width="{w}" height="{h}" alt="{escape(alt)}" {"fetchpriority=high" if eager else "loading=lazy"}><span class="zoom-mark" aria-hidden="true">↗</span></button>'
    tabs = [
      ('library',t('音乐库','Library'),t('好音乐，值得好好收藏。','Good music deserves a home.'),t('从歌曲、专辑和艺术家浏览自己的收藏。管理播放队列，顺序播放、循环或随机，按你喜欢的方式听。','Browse your collection by song, album and artist. Shape the queue, repeat a favorite or let shuffle take the lead.')),
      ('tags',t('标签','Tags'),t('按心情，也按你的方式。','Find a mood. Make it yours.'),t('不只按流派。给歌曲加上“日落”“雨天”“在路上”，用自己熟悉的语言，让喜欢的歌更容易找到。','Go beyond genres. Tag a song with “sunset,” “rainy day” or “on the road,” and find it in words that mean something to you.')),
      ('spaces',t('音乐空间','Music Spaces'),t('让合适的歌，自己聚在一起。','Let the right songs come together.'),t('用标签等规则建立智能分类，也可以手动编排歌单。为专注的午后、安静的清晨，留出不同的音乐空间。','Build smart collections with tag-based rules, or arrange a playlist by hand. Make a musical space for a focused afternoon or a quiet morning.')),
    ]
    buttons=''.join(f'<button role="tab" id="tab-{key}" aria-controls="panel-{key}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}">{name}</button>' for i,(key,name,_,_) in enumerate(tabs))
    panels=''.join(f'<div role="tabpanel" id="panel-{key}" aria-labelledby="tab-{key}" {"hidden" if i else ""}><div class="gallery-copy"><h3>{title}</h3><p>{text}</p></div>{screen("mac-"+key,name+t(" · Mac 真实界面"," · real Mac interface"))}</div>' for i,(key,name,title,text) in enumerate(tabs))
    faq=[
      (t('里面有可以直接听的音乐吗？','Does it include music to stream?'),t('Memory Music 播放和整理你自己准备的本地音乐文件，不提供音乐曲库、音乐下载或流媒体订阅。','Memory Music plays and organizes local music files you bring. It does not supply a streaming catalog, music downloads or a music subscription.')),
      (t('iCloud 会把音乐文件传到其他设备吗？','Does iCloud transfer my audio files?'),t('Pro 同步标签、歌单、音乐记忆等整理信息，不上传原始音频。每台设备仍需准备自己的音乐文件；同步也不能代替原始文件备份。','Pro syncs organization information such as tags, playlists and music memories, not original audio. Each device needs its own music files. Sync is not a replacement for audio backups.')),
      (t('订阅结束后，已有资料怎么办？','What happens when a subscription ends?'),t('已有标签、智能分类、记忆与其他资料保留，仍可使用、编辑和导出。超过免费数量时无法新建更多标签或智能分类，Pro 同步与 CarPlay 停止使用。','Your existing tags, smart collections, memories and other information remain available to use, edit and export. Creating more tags or smart collections above the free limits, Pro sync and CarPlay require active Pro access.')),
      (t('换设备后，怎样恢复 Pro？','How do I restore Pro on another device?'),t('使用购买时的同一 Apple 账户，在 App 内选择“恢复购买”。它恢复的是有效的 Pro 权益；音乐文件和整理资料需要另行准备、同步或从备份恢复。','Use the Apple Account you purchased with, then choose Restore Purchases in the app. This restores valid Pro access; music files and library information are supplied, synced or restored separately.')),
      (t('封面补全和音频指纹识别收费吗？','Are artwork and fingerprint tools paid?'),t('这两项功能属于免费范围。在线查询需要网络，并受第三方服务的可用性与使用条件约束；音频指纹查询可能需要自行配置 AcoustID Client Key。','Both are free features. Online lookups require a network connection and are subject to third-party availability and terms. Fingerprint lookups may require your own AcoustID Client Key.')),
    ]
    faqs=''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in faq)
    free=[t('本地歌曲数量不限，播放与后台聆听','Unlimited local songs, playback & background listening'),t('手动歌单、音乐记忆与备注','Manual playlists, music memories & notes'),t('10 个自定义标签、3 个智能分类','10 custom tags & 3 smart collections'),t('批量封面补全、音频指纹识别','Batch artwork & audio fingerprint tools'),t('资料备份、恢复与导出','Library backup, restore & export')]
    pro=[t('不限数量的新标签与智能分类','Unlimited new tags & smart collections'),t('通过 iCloud 同步整理信息','Organization sync through iCloud'),t('CarPlay 车载聆听','CarPlay listening')]
    freeitems=''.join(f'<li>{x}</li>' for x in free)
    proitems=''.join(f'<li>{x}</li>' for x in pro)
    return f'''<!doctype html>
<html lang="{'zh-CN' if zh else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Memory Music · {t('你的音乐，你的记忆','Your music. Your memories.')}</title>
<meta name="description" content="{t('给自己的音乐一个家。用标签、智能分类、歌单与音乐记忆，整理和聆听你的本地音乐。为 Mac、iPhone 与 iPad 打造。','A home for your music. Organize and enjoy your local collection with tags, smart collections, playlists and music memories. For Mac, iPhone and iPad.')}">
<meta name="theme-color" content="#fbfbfd"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'self'; form-action 'none'">
<link rel="icon" href="{base}icon.png"><link rel="stylesheet" href="{base}product.css"><script src="{base}product.js" defer></script></head>
<body><a class="skip" href="#main">{t('跳至正文','Skip to content')}</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="{prefix}"><img src="{base}icon.png" alt="" width="32" height="32">Memory Music</a><nav aria-label="{t('主导航','Main navigation')}"><a href="#highlights">{t('亮点','Highlights')}</a><a href="#pricing">{t('价格','Pricing')}</a><a href="{prefix}support/">{t('支持','Support')}</a><a class="lang" href="{base+'en/' if zh else base}">{t('EN','中文')}</a></nav></div></header>
<main id="main"><section class="hero"><p class="eyebrow">MEMORY MUSIC</p><h1>{t('有些歌，<br>一听就是那一年。','Some songs take you<br>right back.')}</h1><p class="hero-lead">{t('本地音乐播放器，也是你的音乐记忆库。','A local music player. A home for your memories.')}</p><p class="hero-sub">{t('用自己的方式整理，听见每一首的故事。','Organize your way. Keep the story behind every song.')}</p><div class="hero-actions"><a class="pill" href="#highlights">{t('看看它能做什么','Explore the features')} ↓</a><a class="text-link" href="#pricing">{t('了解免费与 Pro','Free & Pro')} ›</a></div><p class="platforms">Mac · iPhone · iPad <span>{t('发行准备中','Preparing for release')}</span></p><figure class="hero-stage"><div class="mac-device">{screen('mac-tags',t('Mac 标签页面，示例分类','Mac tags screen with sample categories'),True)}<div class="mac-foot"></div></div><div class="phone-device">{screen('iphone-tags',t('iPhone 标签页面','iPhone tags screen'),True)}</div><figcaption>{t('真实应用界面，使用示例歌曲、文字与原创封面。','Real app screens with sample songs, text and original artwork.')}</figcaption></figure></section>
<section class="gallery-section section" id="highlights"><div class="section-heading"><p class="eyebrow">{t('每一种喜欢，都有位置','MAKE IT PERSONAL')}</p><h2>{t('音乐很多。<br>找到喜欢的，很简单。','A whole collection.<br>A little more personal.')}</h2><p>{t('从一份自己的曲库开始，把整理变成聆听的一部分。','Start with the music you own. Make organizing part of listening.')}</p></div><div class="gallery"><div class="tablist" role="tablist" aria-label="{t('探索应用界面','Explore app screens')}">{buttons}</div>{panels}</div></section>
<section class="memory-section"><div class="memory-layout section"><div class="memory-copy"><p class="eyebrow">{t('音乐记忆','MUSIC MEMORIES')}</p><h2>{t('不只记住歌名。<br>也记住那一天。','Keep the song.<br>Keep the moment.')}</h2><p>{t('一段旅程，一个人，某个普通却难忘的傍晚。为歌曲留下记忆与备注，下次再听，故事也一起回来。','A journey. A person. An ordinary evening you never forgot. Leave a memory or a note with a song, ready for the next listen.')}</p><div class="memory-quote"><span>{t('示例音乐记忆','A SAMPLE MUSIC MEMORY')}</span><blockquote>{t('“那天在海边走了很久。回来的路上，<br>这首歌一直没有切掉。”','“We walked by the sea for hours.<br>I kept this song on all the way home.”')}</blockquote></div><p class="fine">{t('记忆与备注免费使用。配图为真实歌曲记忆编辑界面。','Memories and notes are free. Shown: the actual song memory editor.')}</p></div><div class="memory-visual"><div class="phone-device">{screen('iphone-memory',t('歌曲记忆编辑界面，示例内容','Song memory editor with sample content'))}</div></div></div></section>
<section class="devices section"><div class="section-heading"><p class="eyebrow">MAC · IPHONE · IPAD</p><h2>{t('在桌前认真整理。<br>带着喜欢的出门。','Organize at your desk.<br>Take your favorites along.')}</h2><p>{t('大屏浏览，也能随身聆听。Pro 让标签、歌单和音乐记忆，<br>通过同一 iCloud 账户在设备间同步。','Browse on a bigger screen. Listen wherever you go.<br>With Pro, sync tags, playlists and memories through the same iCloud account.')}</p></div><div class="devices-stage"><div class="tablet-device">{screen('ipad-library',t('iPad 本地音乐库，示例歌曲','iPad local library with sample songs'))}</div><div class="phone-device">{screen('iphone-library',t('iPhone 本地音乐库，示例歌曲','iPhone local library with sample songs'))}</div></div><p class="fine center">{t('整理信息同步属于 Pro。原始音频不上传到 CloudKit，每台设备仍需准备自己的音乐文件。','Organization sync requires Pro. Original audio is not uploaded to CloudKit; each device needs its own music files.')}</p></section>
<section class="details-section section"><div class="section-heading left"><p class="eyebrow">{t('日常里的细节','THE EVERYDAY DETAILS')}</p><h2>{t('从整理到播放，<br>照顾每一步。','From your collection<br>to your next listen.')}</h2></div><div class="detail-grid"><article class="detail-card artwork"><span class="feature-symbol" aria-hidden="true">♫</span><span class="badge">{t('免费','FREE')}</span><h3>{t('让音乐资料，<br>更完整一点。','Fill in<br>the details.')}</h3><p>{t('批量查找封面，使用音频指纹辅助识别歌曲。先预览结果，再决定要不要应用。','Look up artwork in batches and use audio fingerprints to help identify a song. Preview results and choose what to apply.')}</p><div class="cover-strip" aria-hidden="true"><span></span><span></span><span></span></div></article><article class="detail-card carplay"><span class="feature-symbol" aria-hidden="true">↗</span><span class="badge">PRO</span><h3>{t('熟悉的音乐，<br>陪你在路上。','Your music.<br>Along for the ride.')}</h3><p>{t('CarPlay 作为 Pro 功能，把本地音乐的聆听延伸到支持的车载环境。','CarPlay is included with Pro, bringing your local music to a compatible in-car environment.')}</p><p class="detail-foot">{t('需要支持 CarPlay 的 iPhone 与车载设备。','Requires a compatible iPhone and CarPlay system.')}</p></article></div></section>
<section class="ownership section"><div><p class="eyebrow">{t('自己的收藏，自己掌握','YOUR COLLECTION, IN YOUR HANDS')}</p><h2>{t('音乐是你的。<br>记忆也是。','Your music.<br>Your memories, too.')}</h2></div><div class="ownership-list"><article><h3>{t('从自己的音乐开始','Bring your own music')}</h3><p>{t('添加本地音乐目录，不需要另建 Memory Music 账户。原始文件由你自己保管。','Add your local music folders. No separate Memory Music account is needed. You keep your original files.')}</p></article><article><h3>{t('留一份自己的备份','Keep a backup of your own')}</h3><p>{t('导出支持的整理资料和用户资源，需要时预览并恢复。备份与导出免费使用。','Export supported organization information and user resources, then preview a backup before restoring. Backup and export are free.')}</p></article><article><h3>{t('清楚了解数据去向','Know where information goes')}</h3><p>{t('本机资料、私人 iCloud 同步和主动触发的在线查询，分别说明。','Local information, private iCloud sync and optional online lookups are explained separately.')}</p><a class="text-link" href="{prefix}privacy/">{t('阅读隐私政策','Read the privacy policy')} ›</a></article></div></section>
<section class="pricing-section" id="pricing"><div class="section"><div class="section-heading"><p class="eyebrow">FREE & PRO</p><h2>{t('先好好听歌。<br>再选择适合自己的 Pro。','Enjoy your music.<br>Choose Pro when it fits.')}</h2><p>{t('免费功能可以长期使用。三种 Pro 方式，解锁同一套完整功能。','Keep using the free features. Three ways to Pro, with the same full feature set.')}</p></div><div class="pricing-grid"><article class="free-plan"><span class="plan-label">MEMORY MUSIC</span><h3>{t('免费','Free')}</h3><p>{t('把日常聆听与整理，留给每个人。','For everyday listening and organizing.')}</p><ul>{freeitems}</ul></article><article class="pro-plan"><span class="plan-label">MEMORY MUSIC PRO</span><h3>{t('更多空间，更多陪伴。','More room for your music.')}</h3><ul>{proitems}</ul><div class="price-options"><div><span>{t('月订阅','Monthly')}</span><strong>US$1.99</strong><small>{t('每月','per month')}</small></div><div><span>{t('年订阅','Yearly')}</span><strong>US$14.99</strong><small>{t('每年，一次收取','per year, billed annually')}</small></div><div><span>{t('永久买断','Lifetime')}</span><strong>US$49.99</strong><small>{t('一次购买','one-time purchase')}</small></div></div><p class="fine">{t('以上为计划首发的美国区价格，其他地区以 App 内 Apple 显示为准。App 尚在发行准备中，本页不提供购买。','Planned US launch prices. Regional prices are shown by Apple in the app. The app is preparing for release; purchases are not offered on this page.')}</p></article></div><p class="pricing-note">{t('订阅自动续订，可在 Apple 账户中管理或取消。订阅到期后，已有资料保留并可使用、编辑和导出；新增超额内容、同步与 CarPlay 需要有效 Pro。购买永久版不会自动取消已有订阅。','Subscriptions renew automatically and can be managed or canceled in your Apple Account. Existing information remains usable, editable and exportable after expiry; new over-limit content, sync and CarPlay require valid Pro. A lifetime purchase does not automatically cancel an existing subscription.')}</p></div></section>
<section class="faq section"><div><p class="eyebrow">{t('再了解一点','A FEW MORE THINGS')}</p><h2>{t('你可能还想知道。','Good to know.')}</h2></div><div class="faq-list">{faqs}</div></section>
<section class="closing section"><img src="{base}icon.png" width="72" height="72" alt=""><h2>{t('给喜欢的歌，<br>一个自己的家。','A home for<br>the music you love.')}</h2><p>{t('Mac、iPhone 与 iPad 版本正在准备正式发行。<br>当前 App 界面以简体中文为主。','Preparing for release on Mac, iPhone and iPad.<br>The app interface is currently primarily Simplified Chinese.')}</p><a class="pill" href="{prefix}support/">{t('使用支持与联系','Support & contact')} ↗</a></section></main>
<footer><div class="footer-inner"><a class="brand" href="{prefix}">Memory Music</a><nav aria-label="{t('页脚导航','Footer navigation')}"><a href="{prefix}privacy/">{t('隐私政策','Privacy')}</a><a href="{prefix}support/">{t('使用支持','Support')}</a><a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">{t('使用条款','Terms')}</a><a href="mailto:{escape(email)}">{escape(email)}</a></nav><p>{t('配图为实际 App 界面渲染，使用虚构歌曲、示例文字和原创抽象封面，不包含私人音乐资料。','Images render actual app screens with fictional songs, sample text and original abstract artwork. No private music library is shown.')}</p><small>© 2026 Memory Music</small></div></footer><dialog id="image-viewer" aria-label="{t('放大界面','Enlarged app screen')}"><button class="close-viewer" autofocus aria-label="{t('关闭图片','Close image')}">×</button><img alt=""><p></p></dialog></body></html>'''
